<script nonce="{{ csrf_token() }}">
var requestableSpecificationFields=@json($specificationFields->map(fn($field)=>['name'=>$field->name,'numeric'=>$field->format==='numeric','values'=>collect($field->formatFieldValuesAsArray())->except('')->values()])->values());
function requestLineForModel(id){var q=parseInt($('#model-booking-quantity-'+id).val(),10),d=parseInt($('#model-booking-discipline-'+id).val(),10),c=parseInt($('#model-booking-company-'+id).val(),10);if(!q||!d||!c){window.alert('Enter a total needed quantity, discipline, and destination site for each model.');return null}return{model_id:id,quantity:q,discipline_id:d,company_id:c}}
$(document).on('click','.add-model-to-request-cart',function(){var l=requestLineForModel(+$(this).data('model-id'));if(l)addLinesToRequestCart([l],false)});
$(function(){
var $t=$('#requestableModelsTable'),$category=$('#requestableModelsCategoryFilter'),tokens=[];
if(!$t.length)return;
var $input=$('.fixed-table-toolbar .search input').attr('placeholder','Search models or add a technical filter'),$menu=$('<div class="dropdown-menu" id="requestableSpecificationSuggestions"></div>').css({maxHeight:'240px',overflowY:'auto',zIndex:1050}),$chips=$('#requestableSpecificationChips');
$input.parent().css('position','relative').append($menu);
function text(row){return $('<div>').html(row.specifications||'').text().replace(/\s+/g,' ').trim()}
function fieldFor(value){var lower=value.toLowerCase();return requestableSpecificationFields.find(function(field){return lower.indexOf(field.name.toLowerCase())===0})}
function apply(){var category=$category.val();$t.bootstrapTable('filterBy',category?{category:category}:{},{filterAlgorithm:function(row){if(category&&$('<div>').html(row.category||'').text().trim()!==category)return false;var specifications=text(row);return tokens.every(function(token){if(token.field.numeric){var match=specifications.match(new RegExp(token.field.name.replace(/[.*+?^\${}()|[\]\\]/g,'\\$&')+':\\s*([0-9.]+)','i'));if(!match)return false;var number=parseFloat(match[1]);return token.operator==='>='?number>=token.number:token.operator==='<='?number<=token.number:number===token.number}return specifications.toLowerCase().indexOf((token.field.name+': '+token.value).toLowerCase())!==-1})}})}
function renderChips(){$chips.empty();tokens.forEach(function(token,index){$chips.append($('<button type="button" class="btn btn-default btn-sm" style="margin-right:5px"></button>').text(token.field.name+' '+(token.operator===':'?'is':token.operator)+' '+token.value+' ×').on('click',function(){tokens.splice(index,1);apply()}))});}
function addToken(field,operator,value){value=$.trim(value);if(!value)return;var token={field:field,operator:operator,value:value,number:parseFloat(value)};if(field.numeric&&isNaN(token.number))return;tokens.push(token);$input.val('');$menu.hide();renderChips();apply();}
function show(items){$menu.empty();items.forEach(function(item){$menu.append($('<button type="button" class="dropdown-item btn btn-link btn-block text-left"></button>').text(item.label).on('click',item.action))});$menu.toggle(items.length>0)}
function suggest(){var value=$.trim($input.val()),field=fieldFor(value);if(!field){var matches=requestableSpecificationFields.filter(function(candidate){return candidate.name.toLowerCase().indexOf(value.toLowerCase())!==-1});show(matches.slice(0,8).map(function(candidate){return{label:candidate.name,action:function(){$input.val(candidate.name+(candidate.numeric?' >= ':': ')).focus();suggest()}}}));return}var remainder=$.trim(value.slice(field.name.length));if(!remainder){show([{label:field.name+(field.numeric?' ≥ value':': value'),action:function(){$input.val(field.name+(field.numeric?' >= ':': ')).focus();suggest()}}]);return}var operator=(remainder.match(/^(>=|<=|=|:)/)||[])[1];if(field.numeric&&!operator){show(['>=','<=','='].map(function(choice){return{label:choice,action:function(){$input.val(field.name+' '+choice+' ').focus();suggest()}}}));return}var typed=$.trim(remainder.replace(/^(>=|<=|=|:)/,''));if(field.values.length){show(field.values.filter(function(candidate){return candidate.toLowerCase().indexOf(typed.toLowerCase())!==-1}).slice(0,8).map(function(candidate){return{label:candidate,action:function(){addToken(field,operator||':',candidate)}}}));return}$menu.hide()}
function commit(){var value=$.trim($input.val()),field=fieldFor(value);if(!field)return false;var remainder=$.trim(value.slice(field.name.length)),match=remainder.match(/^(>=|<=|=|:)\s*(.+)$/);if(!match)return false;addToken(field,match[1],match[2]);return true}
$input.on('input',suggest).on('keydown',function(event){if(event.key==='Enter'&&commit())event.preventDefault();if(event.key==='Escape')$menu.hide()}).on('blur',function(){setTimeout(function(){$menu.hide()},150)});
var bootstrapTable=$t.data('bootstrap.table'),selected=bootstrapTable&&bootstrapTable.filterColumns?bootstrapTable.filterColumns.category:'';$category.val(selected||'').on('change',apply);if(selected)apply();
});
</script>
